import { Controller, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const APPROVED = '승인';

function optionalText(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  return String(value);
}

function requiredId(value: unknown, label: string): string {
  const text = value === undefined || value === null ? '' : String(value).trim();
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 올바르게 입력해 주세요.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr02505Controller {
  @Post('/asset-inspection-plans/:assetInspectionPlanId/link')
  @HttpCode(200)
  async linkAssetInspectionPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const planId = requiredId(req.params['assetInspectionPlanId'], '자산실사 계획 ID');
    return transaction(async (db) => {
      const plans = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM asset_inspection_plan WHERE asset_inspection_plan_id = CAST(:planId AS bigint)',
        { planId },
      );
      if (plans.length === 0) {
        throw new ApiError(404, 'ASSET_INSPECTION_PLAN_NOT_FOUND', '자산실사 계획을 찾을 수 없습니다.');
      }
      if (plans[0].approvalStatus !== APPROVED) {
        throw new ApiError(409, 'ASSET_INSPECTION_PLAN_NOT_APPROVED', '승인되지 않은 계획은 실사를 처리할 수 없습니다.');
      }
      // 가정: 외부 시스템 호출 수단이 없어 연계 요청 이력만 REQUESTED로 남긴다.
      const rows = await db.query(
        `INSERT INTO link_log (requester_id, link_target, status, requested_at, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), 'ASSET_INSPECTION', 'REQUESTED', now(), now(), now())
         RETURNING status AS "linkStatus", failure_reason AS "failureReason"`,
        { userId: user.id },
      );
      return rows[0];
    });
  }

  @Post('/asset-inspection-items/receive')
  @HttpCode(200)
  async receiveAssetInspectionResults(@Req() req: Request) {
    const user = currentUser(req);
    const data = checks.inputOf(req.body);
    const planId = requiredId(data.assetInspectionPlanId, '자산실사 계획 ID');
    const assetId = requiredId(data.assetId, '자산 ID');
    const inspectionResult = optionalText(data.inspectionResult);
    if (inspectionResult !== null && inspectionResult.length > 20) {
      throw new ApiError(400, 'VALIDATION_FAILED', '실사 결과는 20자 이내로 입력해 주세요.');
    }
    const inspectedAt = optionalText(data.inspectedAt);
    if (inspectedAt !== null && !/^\d{4}-\d{2}-\d{2}/.test(inspectedAt)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '실사 일시 형식이 올바르지 않습니다.');
    }
    const remark = optionalText(data.remark);
    return transaction(async (db) => {
      const plans = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM asset_inspection_plan WHERE asset_inspection_plan_id = CAST(:planId AS bigint)',
        { planId },
      );
      if (plans.length === 0) {
        throw new ApiError(404, 'ASSET_INSPECTION_PLAN_NOT_FOUND', '자산실사 계획을 찾을 수 없습니다.');
      }
      if (plans[0].approvalStatus !== APPROVED) {
        throw new ApiError(409, 'ASSET_INSPECTION_PLAN_NOT_APPROVED', '승인되지 않은 계획의 결과는 저장할 수 없습니다.');
      }
      const assets = await db.query(
        'SELECT asset_id AS "assetId" FROM asset WHERE asset_id = CAST(:assetId AS bigint)',
        { assetId },
      );
      if (assets.length === 0) {
        throw new ApiError(422, 'ASSET_NOT_IN_INSPECTION_PLAN', '자산이 없거나 실사 대상이 아닙니다.');
      }
      const rows = await db.query(
        `INSERT INTO asset_inspection_item (asset_inspection_plan_id, asset_id, inspection_result, inspected_at, remark, created_at, updated_at)
         VALUES (CAST(:planId AS bigint), CAST(:assetId AS bigint), :inspectionResult, CAST(:inspectedAt AS timestamptz), :remark, now(), now())
         ON CONFLICT (asset_inspection_plan_id, asset_id) DO UPDATE
         SET inspection_result = EXCLUDED.inspection_result,
             inspected_at = EXCLUDED.inspected_at,
             remark = EXCLUDED.remark,
             updated_at = now()
         RETURNING asset_inspection_item_id AS "assetInspectionItemId"`,
        { planId, assetId, inspectionResult, inspectedAt, remark },
      );
      return rows[0];
    });
  }
}

