import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const APPROVAL_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['승인', '승인'],
  ['승인 취소', '승인 취소'],
  ['반려', '반려'],
];
const PROGRESS_OPTIONS: [string, string][] = [
  ['진행', '진행'],
  ['완료', '완료'],
  ['취소', '취소'],
];

export default function FnSfr02505Page({ role, notify }: PageProps) {
  const [type, setType] = useState('');
  const [approval, setApproval] = useState('');
  const [progress, setProgress] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [drawer, setDrawer] = useState<'result' | 'change' | null>(null);
  const [linkFailure, setLinkFailure] = useState('');

  const [assetId, setAssetId] = useState<number | string>('');
  const [inspectionResult, setInspectionResult] = useState('');
  const [inspectedAt, setInspectedAt] = useState('');
  const [remark, setRemark] = useState('');

  const [changeAssetId, setChangeAssetId] = useState<number | string>('');
  const [changeType, setChangeType] = useState('');
  const [changeDate, setChangeDate] = useState('');
  const [changeContent, setChangeContent] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/asset-inspection-plans', role, undefined, { ...applied, page, size: 20 }),
    [role, applied, page],
  );

  function search() {
    setPage(0);
    setApplied({ inspectionType: type, approvalStatus: approval, progressStatus: progress });
  }

  function reset() {
    setType('');
    setApproval('');
    setProgress('');
    setPage(0);
    setApplied({});
  }

  function planId(): string {
    return String(selected ? selected['assetInspectionPlanId'] : '');
  }

  function closeDrawer() {
    setDrawer(null);
  }

  async function link() {
    try {
      const res = await call('POST', '/asset-inspection-plans/' + planId() + '/link', role, {});
      setLinkFailure(res['failureReason'] ? String(res['failureReason']) : '');
      notify('외부 자산실사 시스템 연계를 요청했습니다. 연계 상태: ' + String(res['linkStatus']));
    } catch (e) {
      setLinkFailure(e instanceof Error ? e.message : '연계에 실패했습니다.');
    }
  }

  async function complete() {
    try {
      await call('POST', '/asset-inspection-plans/' + planId() + '/complete', role, {});
      notify('실사를 완료 처리했습니다.');
      setSelected(null);
      list.reload();
    } catch (e) {
      setLinkFailure(e instanceof Error ? e.message : '완료 처리에 실패했습니다.');
    }
  }

  async function submitResult() {
    if (assetId === '') {
      throw new Error('자산을 선택해 주세요.');
    }
    await call('POST', '/asset-inspection-items/receive', role, {
      assetInspectionPlanId: Number(planId()),
      assetId,
      inspectionResult,
      inspectedAt,
      remark,
    });
    notify('실사 결과를 저장했습니다.');
    setAssetId('');
    setInspectionResult('');
    setInspectedAt('');
    setRemark('');
    closeDrawer();
  }

  async function submitChange() {
    if (changeAssetId === '' || changeType === '' || changeDate === '' || changeContent === '') {
      throw new Error('자산, 변동 유형, 변동 일자, 변동 내용을 모두 입력해 주세요.');
    }
    await call('POST', '/asset-changes', role, {
      assetId: changeAssetId,
      changeType,
      changeDate,
      changeContent,
    });
    notify('자산 변동을 등록했습니다.');
    setChangeAssetId('');
    setChangeType('');
    setChangeDate('');
    setChangeContent('');
    closeDrawer();
  }

  if (selected) {
    const approved = selected['approvalStatus'] === '승인';
    const inProgress = selected['progressStatus'] === '진행';
    return (
      <div className="doc">
        <button
          className="ghost"
          onClick={() => {
            setSelected(null);
            setLinkFailure('');
          }}
        >
          목록으로 돌아가기
        </button>
        <section className="box">
          <h2>실사 계획</h2>
          <Pairs
            items={[
              ['자산실사 계획 ID', String(selected['assetInspectionPlanId'])],
              ['실사 유형', String(selected['inspectionType'])],
              ['실사 시작일', <DateText value={selected['startDate']} />],
              ['실사 종료일', <DateText value={selected['endDate']} />],
              ['승인 처리 상태', <Badge value={selected['approvalStatus']} />],
              ['진행 상태', <Badge value={selected['progressStatus']} />],
            ]}
          />
        </section>
        <section className="box">
          <h2>실사 처리</h2>
          {approved ? null : <p>승인된 계획만 실사를 처리할 수 있습니다.</p>}
          {linkFailure ? <ErrorText text={linkFailure} /> : null}
          <div>
            {approved ? <button onClick={link}>외부 시스템과 연계</button> : null}
            {approved ? (
              <button className="ghost" onClick={() => setDrawer('result')}>
                실사 결과 입력
              </button>
            ) : null}
            {approved ? (
              <button className="ghost" onClick={() => setDrawer('change')}>
                자산 변동 등록
              </button>
            ) : null}
            {inProgress ? (
              <button className="ghost" onClick={complete}>
                실사 완료 처리
              </button>
            ) : null}
          </div>
        </section>
        {drawer === 'result' ? (
          <Drawer title="실사 결과 입력" onClose={closeDrawer}>
            <Form onSubmit={submitResult} submit="저장">
              <Field label="자산 ID" required>
                <LookupSelect table="asset" role={role} value={assetId} onChange={setAssetId} />
              </Field>
              <Field label="실사 결과">
                <TextInput value={inspectionResult} onChange={setInspectionResult} />
              </Field>
              <Field label="실사 일시">
                <DateInput value={inspectedAt} onChange={setInspectedAt} />
              </Field>
              <Field label="비고" wide>
                <TextInput value={remark} onChange={setRemark} multiline />
              </Field>
            </Form>
          </Drawer>
        ) : null}
        {drawer === 'change' ? (
          <Drawer title="자산 변동 등록" onClose={closeDrawer}>
            <Form onSubmit={submitChange} submit="등록">
              <Field label="자산" required>
                <LookupSelect table="asset" role={role} value={changeAssetId} onChange={setChangeAssetId} />
              </Field>
              <Field label="변동 유형" required>
                <TextInput value={changeType} onChange={setChangeType} />
              </Field>
              <Field label="변동 일자" required>
                <DateInput value={changeDate} onChange={setChangeDate} />
              </Field>
              <Field label="변동 내용" required wide>
                <TextInput value={changeContent} onChange={setChangeContent} multiline />
              </Field>
            </Form>
          </Drawer>
        ) : null}
      </div>
    );
  }

  const data = list.data;
  return (
    <div className="doc">
      <section className="box">
        <h2>자산실사 진행 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="실사 유형">
            <TextInput value={type} onChange={setType} />
          </Field>
          <Field label="승인 처리 상태">
            <Select value={approval} onChange={setApproval} options={APPROVAL_OPTIONS} />
          </Field>
          <Field label="진행 상태">
            <Select value={progress} onChange={setProgress} options={PROGRESS_OPTIONS} />
          </Field>
        </Filters>
        {list.error ? <ErrorText text={list.error} /> : null}
        <Band total={data ? data.total : 0} />
        <DataTable
          columns={[
            { key: 'assetInspectionPlanId', label: '자산실사 계획 ID' },
            { key: 'inspectionType', label: '실사 유형' },
            {
              key: 'startDate',
              label: '실사 기간',
              render: (row) => (
                <span>
                  <DateText value={row['startDate']} /> ~ <DateText value={row['endDate']} />
                </span>
              ),
            },
            { key: 'approvalStatus', label: '승인 처리 상태', render: (row) => <Badge value={row['approvalStatus']} /> },
            { key: 'progressStatus', label: '진행 상태', render: (row) => <Badge value={row['progressStatus']} /> },
          ]}
          rows={data ? data.items : []}
          onRowClick={(row) => setSelected(row)}
          empty="조건에 맞는 실사 계획이 없습니다. 조회 조건을 바꿔 다시 조회해 주세요."
        />
        <Pager page={page} size={data ? data.size : 20} total={data ? data.total : 0} onPage={setPage} />
      </section>
    </div>
  );
}
